(() => {
'use strict';
const KEY='daily-reading-v1', labels={today:'今日精读',library:'精读课库',wrong:'错题本',saved:'我的收藏',manage:'课程与备份'};
const $=s=>document.querySelector(s), esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const Core=window.ReadingCore;
let state={progress:{},custom:[]}, storageOK=true, translation=false, fontSize=18; const translated=new Set();
try {const raw=localStorage.getItem(KEY); if(raw){const parsed=JSON.parse(raw);validateState(parsed);state=parsed;}}catch(e){storageOK=false;}
const shared=()=>Core.available(window.SEED_LESSONS);
const all=()=>[...shared(),...state.custom];
const progress=id=>state.progress[id]||(state.progress[id]={answers:{},checks:{},vocab:{},notes:'',bookmark:false,attempts:[],wrong:[]});
function save(){try{localStorage.setItem(KEY,JSON.stringify(state));storageOK=true;$('#save-state').textContent='已保存';}catch(e){storageOK=false;$('#save-state').textContent='保存失败，请导出备份';}updateCount();}
function toast(t){$('#toast').textContent=t;$('#toast').classList.add('show');clearTimeout(toast.t);toast.t=setTimeout(()=>$('#toast').classList.remove('show'),2500);}
function updateCount(){$('#wrong-count').textContent=Object.values(state.progress).reduce((n,p)=>n+(p.wrong||[]).length,0);}
function validateLesson(l){return Core.validateLesson(l);}
function validateState(s){return Core.validateState(s,window.SEED_LESSONS);}
function route(){const parts=location.hash.slice(1).split('/');const id=parts[0]==='lesson'?parts[1]:(shared().at(-1)||all()[0])?.id;return{view:parts[0]||'today',id,tab:parts[2]||'quiz'};}
function stats(){const done=Object.values(state.progress).filter(p=>Object.values(p.checks).filter(Boolean).length===4).length, attempts=Object.values(state.progress).flatMap(p=>p.attempts||[]),words=Object.values(state.progress).reduce((n,p)=>n+Object.values(p.vocab||{}).filter(Boolean).length,0);return `<div class="stats"><div class="stat"><div><small>已完成精读</small><br><strong>${done}<span>/ ${all().length} 篇</span></strong></div><span class="icon">▤</span></div><div class="stat"><div><small>最近答题得分</small><br><strong>${attempts.length?Math.round([...attempts].sort((a,b)=>a.date.localeCompare(b.date)).at(-1).score):'—'}<span>/ 100</span></strong></div><span class="icon">◎</span></div><div class="stat"><div><small>已掌握词汇</small><br><strong>${words}<span>个</span></strong></div><span class="icon">✧</span></div></div>`;}
function heading(title,sub){return `<div class="greeting"><div><span class="eyebrow">DAILY READING / 每日向前一点</span><h1>${title}</h1><p>${sub}</p></div><span class="date-tag">${new Intl.DateTimeFormat('zh-CN',{timeZone:'Asia/Shanghai',year:'numeric',month:'long',day:'numeric'}).format(new Date())}</span></div>`;}
function render(){const r=route();if(timerId&&(timerId!==r.id||!['today','lesson'].includes(r.view)))pauseTimer();const nav=r.view==='lesson'?'today':r.view;document.querySelectorAll('[data-nav]').forEach(a=>{a.classList.toggle('active',a.dataset.nav===nav);if(a.dataset.nav===nav)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current');});$('#breadcrumb').textContent=labels[nav]||'今日精读';let html='';if(r.view==='today'||r.view==='lesson'){const l=all().find(l=>l.id===r.id);html=l?heading('把今天，读深一点。','一篇精读，积累词汇、逻辑与表达。建议每天留出 30 分钟。')+stats()+lesson(l,r.tab):heading('课程未找到','请从精读课库选择一篇文章。')+`<a href="#library">返回课库 →</a>`;}else if(r.view==='library'||r.view==='saved'){const list=all().filter(l=>r.view==='library'||progress(l.id).bookmark);html=heading(labels[r.view],r.view==='library'?'按自己的节奏，完成每一篇。公共课程随网站发布更新，所有人共享相同内容。':'留住值得再读的文章。')+(list.length?`<div class="library-grid">${list.map(card).join('')}${r.view==='library'?`<div class="library-card future"><span class="eyebrow">WHAT’S NEXT / 学习方向</span><h2>让阅读，成为习惯。</h2><p>公共新课通过 GitHub 更新发布。若今日尚无新课，会继续展示最近一期；本地导入课程仅你自己可见。</p><a href="#manage">课程管理与备份 →</a></div>`:''}</div>`:empty('☆','还没有收藏文章','点击文章右上角的星标，放入你的专属课单。'));}else if(r.view==='wrong'){html=heading('从错题里，多学一步。','提交后自动收录错题；答对后自动移出，也可以手动标记已掌握。');let n=0;for(const l of all()){const p=progress(l.id);for(const i of p.wrong){n++;const a=p.attempts.at(-1)?.answers||{};html+=`<section class="manage-card"><span class="eyebrow">DAY ${l.day} · ${esc(l.title)}</span>${question(l,i,a,true)}<div class="actions"><button data-master="${esc(l.id)}" data-index="${i}">✓ 已掌握，移出错题本</button><a class="review-link" href="#lesson/${esc(l.id)}/quiz">重新答题 →</a></div></section>`;}}if(!n)html+=empty('◎','这里暂时没有错题','完成阅读理解后，答错的题会自动收录，方便你回头巩固。');}else if(r.view==='manage'){html=manage();}else html=heading('找不到这个页面','从左侧导航继续学习。');$('#main').innerHTML=(!storageOK?'<p class="warn">本地记录无法读取或保存。可在“课程与备份”导出当前记录；请检查浏览器存储设置。</p>':'')+html;bind(r);updateCount();}
function empty(icon,title,sub){return `<div class="empty"><span>${icon}</span><h2>${title}</h2><p>${sub}</p><a class="review-link" href="#today">去今日精读 →</a></div>`;}
function card(l){const p=progress(l.id),n=Object.values(p.checks).filter(Boolean).length;return `<article class="library-card"><span class="eyebrow">DAY ${l.day} · ${esc(l.topic)}</span><h2>${esc(l.title)}</h2><p>${esc(l.subtitle)}</p><div class="tags"><span>${l.minutes} 分钟</span><span>${n===4?'已完成':n?'学习中':'待学习'}</span><span>${l.questions.length} 道题</span></div><a href="#lesson/${esc(l.id)}/quiz">${n?'继续学习':'开始精读'} →</a></article>`;}
function lesson(l,tab){if(!['article','translation','quiz','vocab','sentences','writing','review'].includes(tab))tab='quiz';const p=progress(l.id),checks=[['read','通读文章与译文'],['quiz','完成阅读理解'],['vocab','复习核心词汇'],['writing','积累句式与表达']],n=checks.filter(([k])=>p.checks[k]).length;return `<div class="lesson-layout"><article class="lesson-card"><div class="lesson-head"><span class="eyebrow">DAY ${String(l.day).padStart(2,'0')} &nbsp; / &nbsp; ${esc(l.topic)}</span><button class="bookmark" id="bookmark" aria-label="${p.bookmark?'取消收藏':'收藏文章'}" aria-pressed="${p.bookmark}">${p.bookmark?'★':'☆'}</button><h2>${esc(l.title)}</h2><p class="subtitle">${esc(l.subtitle)}</p><div class="tags"><span>${esc(l.level)}</span><span>约 ${l.paragraphs.join(' ').split(/\s+/).length} 词</span><span>${l.minutes} 分钟</span><span>${esc(l.source)}</span><span>${esc(l.date||'自定义课程')}</span></div></div><nav class="tabs" aria-label="课程章节">${[['quiz','01 先看题目'],['article','02 文章精读'],['translation','03 全文翻译'],['vocab','04 核心词汇'],['sentences','05 长难句'],['writing','06 写作积累'],['review','07 最后讲解']].map(([key,name])=>`<button data-tab="${key}" class="${tab===key?'active':''}" ${tab===key?'aria-current="page"':''}>${name}</button>`).join('')}</nav><div class="lesson-body">${tab==='article'?article(l):tab==='translation'?fullTranslation(l):tab==='quiz'?quiz(l):tab==='vocab'?vocab(l):tab==='sentences'?sentences(l):tab==='review'?review(l):writing(l)}</div></article><aside class="right-rail">${timerCard(l)}<section class="rail-card"><h3>今日学习清单</h3><p>每完成一项，就给自己一个肯定。</p><div class="checklist">${checks.map(([k,t])=>`<label><input type="checkbox" data-check="${k}" ${p.checks[k]?'checked':''}>${t}</label>`).join('')}</div><div class="progress-track"><div class="progress-fill" style="width:${n/4*100}%"></div></div><div class="progress-label" id="check-progress">已完成 ${n} / 4 项</div></section><section class="rail-card"><span class="eyebrow">TODAY’S THOUGHT</span><p class="tip">“The easiest choice is not always the most valuable one.”</p><p class="tip-cn">最容易的选择，未必最有价值。</p></section><section class="rail-card"><h3>给 600+ 的你</h3><ol><li>先浏览题目，明确要找的信息</li><li>带着题目读原文，定位依据</li><li>解析每一个干扰选项</li><li>用一个新表达写自己的句子</li></ol><p>理解比速度先行，每天积累一点。</p></section></aside></div>`;}
function article(l){return `<details class="question-preview"><summary>随时回看题目 · ${l.questions.length} 道题（不含答案）</summary><ol>${l.questions.map(q=>`<li><p lang="en">${esc(q.stem)}</p><div>${q.options.map((o,i)=>`<p lang="en">${'ABCD'[i]}. ${esc(o)}</p>`).join('')}</div></li>`).join('')}</ol><button data-tab="quiz">返回题目并作答 →</button></details><div class="reader-toolbar"><span>先读英文，遇到难处再打开译文</span><div><button id="font-minus" aria-label="缩小英文字号">A−</button> <button id="font-plus" aria-label="放大英文字号">A+</button> <button id="translation" aria-pressed="${translation}">${translation?'隐藏':'显示'}中文译文</button></div></div><div class="article" style="font-size:${fontSize}px">${l.paragraphs.map((p,i)=>`<section class="paragraph"><span class="para-number">${String(i+1).padStart(2,'0')}</span><p lang="en">${esc(p)}</p><button class="paragraph-translate" data-translate-paragraph="${i}" aria-expanded="${translation||translated.has(l.id+':'+i)}" aria-controls="translation-${i}">${translation||translated.has(l.id+':'+i)?'收起本段译文':'翻译本段'}</button><p id="translation-${i}" class="translation" ${translation||translated.has(l.id+':'+i)?'':'hidden'}>${esc(l.translation[i])}</p></section>`).join('')}</div><div class="reading-end"><span>读完了？检验一下你的理解。</span><button class="primary" data-tab="quiz">回到题目，提交答案 →</button></div>`;}
function question(l,i,answers,submitted){const q=l.questions[i],selected=answers[i];return `<div class="question"><div class="q-label">QUESTION ${String(i+1).padStart(2,'0')} / ${esc(q.skill)}</div><fieldset><legend lang="en">${esc(q.stem)}</legend>${q.options.map((o,j)=>`<label class="option ${submitted?(j===q.answer?'correct':j===selected?'incorrect':''):''}"><input type="radio" name="${esc(l.id)}-q${i}" data-question="${i}" value="${j}" ${selected===j?'checked':''} ${submitted?'disabled':''}><span lang="en">${'ABCD'[j]}. ${esc(o)}</span></label>`).join('')}</fieldset>${submitted?`<div class="explanation"><p><b>正确答案：${'ABCD'[q.answer]} · ${selected===q.answer?'回答正确':'本题需巩固'}</b></p>${q.explanations.map((e,j)=>`<p>${'ABCD'[j]}. ${esc(e)}</p>`).join('')}<p class="evidence">原文依据：${esc(q.evidence)}</p></div>`:''}</div>`;}
function quiz(l){const p=progress(l.id),last=p.attempts.at(-1),submitted=!!p.submitted;return `<p class="section-intro">先看题干与选项，带着问题寻找原文依据。可以先选答案再返回修改，提交前不会显示解析。每题等权计分。</p><div class="question-first-banner"><div><b>先看题目，再读文章</b><p>关注题干中的段落、关键词与提问角度。读原文时也能展开题目速览。</p></div><button class="primary" data-tab="article">带着题目读原文 →</button></div>${submitted?`<div class="score" role="status"><strong>${Math.round(last.score)} <small>/ 100</small></strong><p>答对 ${last.correct} / ${l.questions.length} 题 · 已练习 ${p.attempts.length} 次 · 用时 ${formatTime(last.seconds||0)} · ${last.correct===l.questions.length?'全部答对，继续保持！':p.wrong.length?'错题已加入错题本':'错题已标记掌握，可重新练习巩固'}</p></div>`:''}<form id="quiz-form">${l.questions.map((q,i)=>question(l,i,submitted?last.answers:p.answers,submitted)).join('')}<p id="quiz-error" role="alert" class="error"></p><div class="actions">${submitted?'<button type="button" id="retry">重新练习</button> <button type="button" class="primary" data-tab="vocab">复习核心词汇 →</button>':'<button type="submit" class="primary">提交答案，查看解析</button><span class="section-intro" id="answered">已选择 '+Object.keys(p.answers).length+' / '+l.questions.length+' 题</span>'}</div></form>`;}
function vocab(l){const p=progress(l.id);return `<p class="section-intro">结合原文记忆含义与搭配。勾选“已掌握”，记录自己的词汇积累。</p><div class="vocab-grid">${l.vocabulary.map((v,i)=>`<article class="vocab"><label><input type="checkbox" data-word="${i}" aria-label="已掌握 ${esc(v[0])}" ${p.vocab[i]?'checked':''}></label><h3 lang="en">${esc(v[0])}</h3><small>${esc(v[1])}</small><p>${esc(v[2])}</p><div class="example" lang="en">${esc(v[3])}</div><div class="cn">${esc(v[4])}</div></article>`).join('')}</div><div class="actions"><button data-tab="sentences" class="primary">拆解长难句 →</button></div>`;}
function sentences(l){return `<p class="section-intro">先抓主干，再识别修饰和逻辑关系。不要急着逐词翻译。</p>${l.sentences.map((s,i)=>`<article class="analysis-card"><span class="eyebrow">SENTENCE ${i+1}</span><blockquote lang="en">${esc(s.text)}</blockquote><p><b>结构拆解</b><br>${esc(s.structure)}</p><p><b>参考译文</b><br>${esc(s.meaning)}</p><p>阅读提示 · ${esc(s.tip)}</p></article>`).join('')}<button class="primary" data-tab="writing">积累写作表达 →</button>`;}
function writing(l){return `<p class="section-intro">记住结构，更要写出自己的句子。以下例句均为原创练习表达。</p>${l.expressions.map(s=>`<article class="analysis-card"><p class="expression" lang="en">${esc(s.phrase)}</p><p>${esc(s.meaning)}</p><p lang="en">${esc(s.example)}</p></article>`).join('')}<label for="notes" class="writing-label">轮到你了：围绕本篇主题，使用一个新表达写 2–3 句。</label><textarea id="notes" class="writing" placeholder="In my experience, …">${esc(progress(l.id).notes)}</textarea><p class="section-intro">输入后自动保存 · 可用中英文记录思路</p><button class="primary" data-tab="review">进入最后讲解 →</button>`;}

function fullTranslation(l){return `<p class="section-intro">全文按原文段落顺序翻译。建议独立阅读并作答后，再集中核对。</p><h3 class="translation-title">${esc(l.subtitle)}</h3>${l.paragraphs.map((text,i)=>`<section class="analysis-card translation-card"><span class="eyebrow">PARAGRAPH ${String(i+1).padStart(2,'0')} / 第 ${i+1} 段</span><p lang="en" class="source-paragraph">${esc(text)}</p><p class="full-translation">${esc(l.translation[i])}</p></section>`).join('')}<button class="primary" data-tab="review">结合最后讲解梳理全文 →</button>`;}
function review(l){const r=l.review;return `<p class="section-intro">把零散的词句连成完整理解。建议做题后再看这一部分，最后用自己的话复述。</p>${r?`<section class="review-summary"><span class="eyebrow">THE BIG PICTURE / 一句话读懂</span><h3>这篇文章究竟想说什么？</h3><p>${esc(r.summary)}</p></section><section class="analysis-card"><h3>01 · 文章结构：每一段在做什么</h3><ol class="review-list">${r.structure.map(t=>`<li>${esc(t)}</li>`).join('')}</ol></section><section class="analysis-card"><h3>02 · 作者如何把观点讲清楚</h3><ul class="review-list">${r.logic.map(t=>`<li>${esc(t)}</li>`).join('')}</ul></section><section class="analysis-card"><h3>03 · 容易踩中的阅读陷阱</h3><ul class="review-list">${r.traps.map(t=>`<li>${esc(t)}</li>`).join('')}</ul></section>`:`<section class="review-summary"><h3>最后复盘</h3><p>这篇课程还未添加专门的文章讲解。先结合下面的原文依据回顾各题，再尝试概括段落主旨。</p></section>`}<section class="analysis-card"><h3>04 · 五类题型的定位与判断</h3><p class="section-intro">以下会展示正确答案；尚未作答时，建议先返回阅读理解。</p>${l.questions.map((q,i)=>`<details class="review-question"><summary>第 ${i+1} 题 · ${esc(q.skill)} · 展开讲解</summary><p lang="en">${esc(q.stem)}</p><p><b>答案 ${'ABCD'[q.answer]}</b> · ${esc(q.explanations[q.answer])}</p><p class="evidence">${esc(q.evidence)}</p><p>排除重点：${esc(q.explanations[(q.answer+1)%4])}</p></details>`).join('')}</section>${r?`<section class="analysis-card"><h3>05 · 合上文章，检查自己是否真的读懂</h3><ol class="review-list">${r.selfCheck.map(t=>`<li>${esc(t)}</li>`).join('')}</ol><p class="review-takeaway">${esc(r.takeaway)}</p></section>`:''}<div class="actions"><button data-tab="translation">回看全文翻译</button><button data-tab="quiz">回看答题解析</button><button class="primary" data-tab="writing">写下你的理解 →</button></div>`;}

function download(name,data){const blob=new Blob([JSON.stringify(data,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function manage(){return heading('把学习，长久地留下来。','公开课程由维护者发布，个人学习记录仅保存在当前浏览器。')+`<section class="manage-card"><h2>第一次使用与网站管理</h2><p>无需注册，直接进入课程即可做题。成绩、计时和笔记只在当前浏览器保存。小红书内置浏览器与系统浏览器的记录可能不互通；建议固定在一个浏览器学习，换浏览器前先导出备份。</p><p>网站维护者可使用课程编辑工作台修改并下载文件，再提交到自己的 GitHub 仓库发布；普通访客不能更改线上公共内容。</p><a class="review-link" href="editor.html">打开课程编辑工作台 →</a></section><section class="manage-card"><h2>公共课程更新</h2><p>当前最新公共课程：${esc(shared().at(-1)?.date||'暂无')}。每天按北京时间选择最近一期。新课发布后可检查更新，无需登录。</p><button id="refresh-courses">检查课程更新</button><p id="refresh-result" role="status"></p></section><section class="manage-card"><h2>添加下一篇精读</h2><p>下载 Day 1 结构作为模板，修改内容和唯一 id 后导入。支持单个课程对象或课程数组；导入的课程仅保存在本浏览器。</p><div class="actions"><button id="template">下载课程模板 JSON</button><label>导入课程 <input type="file" id="import-lesson" accept=".json,application/json"></label></div><p id="import-result" role="status"></p></section><section class="manage-card"><h2>备份与恢复</h2><p>记录保存在当前设备的当前浏览器，清理浏览器数据可能丢失。导出文件包含课程快照、计时、答题历史、错题、收藏、清单、写作笔记与导入课程。文件含个人笔记，请勿提交到公开仓库。恢复会替换当前全部记录，请先备份。</p><div class="actions"><button id="export">导出学习备份</button><label>选择备份 <input type="file" id="restore-file" accept=".json,application/json"></label><button id="restore" disabled>确认替换并恢复</button></div><p id="restore-result" role="status"></p></section><section class="manage-card"><h2>关于这份学习计划</h2><p>面向六级与考研英语阅读，先练准确理解，再逐步提高速度。课程为原创模拟材料，非官方真题；目标分数不代表效果承诺。</p><p>当前收录 ${all().length} 篇课程。Day 1 为原创模拟材料，非考试真题。每日新课需由维护者启用 GitHub 工作流；未发布新课时沿用最近一期。学习记录不提供账号同步。跨设备使用请导出、导入备份。</p></section>`;}
function bind(r){
 if($('#refresh-courses'))$('#refresh-courses').onclick=()=>refreshCourses(true);
 if($('#timer-toggle'))$('#timer-toggle').onclick=()=>{if(timerRunning)pauseTimer();else{timerId=r.id;timerRunning=true;timerMark=performance.now();}updateTimer();};
const l=all().find(l=>l.id===r.id),p=l?progress(l.id):null;
 document.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>{location.hash=`lesson/${l.id}/${b.dataset.tab}`;});
 if($('#bookmark'))$('#bookmark').onclick=()=>{p.bookmark=!p.bookmark;save();render();toast(p.bookmark?'已收藏文章':'已取消收藏');};
 document.querySelectorAll('[data-check]').forEach(el=>el.onchange=()=>{p.checks[el.dataset.check]=el.checked;save();const n=Object.values(p.checks).filter(Boolean).length;$('.progress-fill').style.width=n/4*100+'%';$('#check-progress').textContent=`已完成 ${n} / 4 项`;$('.stats').outerHTML=stats();});
 document.querySelectorAll('[data-translate-paragraph]').forEach(b=>b.onclick=()=>{const key=l.id+':'+b.dataset.translateParagraph,t=$('#translation-'+b.dataset.translateParagraph),open=t.hidden;t.hidden=!open;b.setAttribute('aria-expanded',String(open));b.textContent=open?'收起本段译文':'翻译本段';if(open)translated.add(key);else{translated.delete(key);if(translation){translation=false;document.querySelectorAll('[data-translate-paragraph]').forEach(other=>{if(other.getAttribute('aria-expanded')==='true')translated.add(l.id+':'+other.dataset.translateParagraph);});$('#translation').setAttribute('aria-pressed','false');$('#translation').textContent='显示中文译文';}}});
 if($('#translation'))$('#translation').onclick=()=>{translation=!translation;translated.clear();render();};
 for(const [id,delta] of [['font-minus',-1],['font-plus',1]])if($('#'+id))$('#'+id).onclick=()=>{fontSize=Math.max(16,Math.min(24,fontSize+delta));$('.article').style.fontSize=fontSize+'px';};
 document.querySelectorAll('[data-question]').forEach(el=>el.onchange=()=>{p.answers[el.dataset.question]=Number(el.value);save();if($('#answered'))$('#answered').textContent=`已选择 ${Object.keys(p.answers).length} / ${l.questions.length} 题`;});
 if($('#quiz-form'))$('#quiz-form').onsubmit=e=>{e.preventDefault();if(p.submitted)return;const missing=l.questions.findIndex((q,i)=>p.answers[i]===undefined);if(missing!==-1){$('#quiz-error').textContent=`还有题目未作答，请先完成第 ${missing+1} 题。`;document.querySelector(`[data-question="${missing}"]`).focus();return;}pauseTimer();const result=Core.grade(l,p.answers),correct=result.correct;p.attempts.push({date:new Date().toISOString(),answers:{...p.answers},correct,score:result.score,seconds:p.elapsed||0});p.wrong=result.wrong;p.submitted=true;p.checks.quiz=true;save();render();$('.score').scrollIntoView({behavior:'smooth',block:'center'});};
 if($('#retry'))$('#retry').onclick=()=>{pauseTimer();p.answers={};p.submitted=false;p.elapsed=0;save();render();toast('新一轮练习已开始，历史记录保留');};
 document.querySelectorAll('[data-word]').forEach(el=>el.onchange=()=>{p.vocab[el.dataset.word]=el.checked;save();$('.stats').outerHTML=stats();});
 if($('#notes'))$('#notes').oninput=e=>{p.notes=e.target.value;save();};
 document.querySelectorAll('[data-master]').forEach(el=>el.onclick=()=>{const pr=progress(el.dataset.master);pr.wrong=pr.wrong.filter(i=>i!==Number(el.dataset.index));save();render();toast('已移出错题本');});
 if($('#template'))$('#template').onclick=()=>download('lesson-template.json',{...window.SEED_LESSONS[0],id:'day-2',day:2});
 if($('#export'))$('#export').onclick=()=>{pauseTimer();download('daily-reading-backup-'+Core.today()+'.json',Core.backup(state,window.SEED_LESSONS));toast('学习备份已导出');};
 if($('#import-lesson'))$('#import-lesson').onchange=async e=>{const out=$('#import-result');try{const file=e.target.files[0];if(!file)return;if(file.size>5000000)throw Error('文件过大，请使用 5MB 以内的 JSON。');const data=JSON.parse(await file.text()),list=Array.isArray(data)?data:[data];if(!list.length)throw Error('课程数组不能为空。');list.forEach(validateLesson);const ids=[...all(),...list].map(l=>l.id);if(new Set(ids).size!==ids.length)throw Error('课程 id 重复，请修改 id 后重试。');state.custom.push(...list);save();out.textContent=`已添加 ${list.length} 篇课程，请到精读课库查看。`;toast('课程已添加');}catch(err){out.textContent='导入失败：'+err.message;}};
 let pending=null;
 if($('#restore-file'))$('#restore-file').onchange=async e=>{pending=null;$('#restore').disabled=true;try{const f=e.target.files[0];if(!f)return;if(f.size>10000000)throw Error('备份需小于 10MB。');pending=Core.restore(JSON.parse(await f.text()),window.SEED_LESSONS);validateState(pending);$('#restore-result').textContent='格式校验通过。点击“确认替换并恢复”后覆盖当前记录。';$('#restore').disabled=false;}catch(err){$('#restore-result').textContent='无法恢复：'+err.message;}};
 if($('#restore'))$('#restore').onclick=()=>{if(!pending)return;pauseTimer();state=pending;save();render();toast('学习记录已恢复');};
}

let timerId=null,timerRunning=false,timerMark=0,lastCheckpoint=0;
function formatTime(seconds){const n=Math.floor(seconds);return `${String(Math.floor(n/60)).padStart(2,'0')}:${String(n%60).padStart(2,'0')}`;}
function tickTimer(){if(!timerRunning)return;const now=performance.now(),p=progress(timerId);p.elapsed=(p.elapsed||0)+Math.max(0,(now-timerMark)/1000);timerMark=now;}
function pauseTimer(){if(timerRunning){tickTimer();timerRunning=false;save();}updateTimer();}
function updateTimer(){if($('#timer-value'))$('#timer-value').textContent=formatTime(progress(route().id).elapsed||0);if($('#timer-toggle'))$('#timer-toggle').textContent=timerRunning?'暂停计时':'开始 / 继续';}
function timerCard(l){return `<section class="rail-card timer-card"><span class="eyebrow">FOCUS / 专注这一篇</span><div id="timer-value" class="timer-value" aria-label="已学习时间">${formatTime(progress(l.id).elapsed||0)}</div><button id="timer-toggle">${timerRunning?'暂停计时':'开始 / 继续'}</button><p>切换课程、隐藏页面或提交时暂停。重新练习会重置本轮计时。</p></section>`;}
setInterval(()=>{tickTimer();if(timerRunning){if(performance.now()-lastCheckpoint>5000){save();lastCheckpoint=performance.now();}updateTimer();}},1000);
document.addEventListener('visibilitychange',()=>{if(document.hidden)pauseTimer();else{render();refreshCourses(false);}});
window.addEventListener('pagehide',pauseTimer);
// Other tabs can update records; adopt them rather than overwriting their progress.
window.addEventListener('storage',e=>{if(e.key===KEY&&e.newValue){try{const next=JSON.parse(e.newValue);validateState(next);timerRunning=false;state=next;render();toast('已同步当前浏览器另一标签页的记录，计时已暂停');}catch{toast('另一标签页的记录格式无效，未覆盖当前记录');}}});
let fetching=false;
async function refreshCourses(manual=false){
 if(fetching)return;fetching=true;let message='';
 try{
  const res=await fetch('courses.json',{cache:'no-store',signal:AbortSignal.timeout(15000)});if(!res.ok)throw Error('HTTP '+res.status);
  const data=await res.json();if(data.version!==1)throw Error('课库版本不支持');Core.validateCollection(data.lessons);
  // Never change the questions attached to a user's existing attempts.
  for(const old of window.SEED_LESSONS){const next=data.lessons.find(l=>l.id===old.id);if(next&&JSON.stringify(old)!==JSON.stringify(next))throw Error('已有课程被修改，请先备份并联系维护者');}
  const added=data.lessons.filter(l=>!window.SEED_LESSONS.some(x=>x.id===l.id));
  if(added.some(l=>state.custom.some(x=>x.id===l.id)))throw Error('新公共课程与本地课程 id 冲突，请先导出备份并调整本地课程 id');
  if(added.length){window.SEED_LESSONS.push(...added);message=`发现 ${added.length} 篇新课，已加入课库。`;if(['manage','library','today'].includes(route().view)){pauseTimer();render();}toast(message);}
  else message='已检查：当前为最新课库。';
 }catch(e){message='更新未完成，继续使用已加载课程。'+(manual?' '+e.message:'');if(manual)toast(message);}
 finally{fetching=false;if(manual&&$('#refresh-result'))$('#refresh-result').textContent=message;}
}

$('.skip').onclick=e=>{e.preventDefault();$('#main').focus();$('#main').scrollIntoView();};
window.addEventListener('hashchange',()=>{render();window.scrollTo(0,0);});render();refreshCourses(false);setInterval(()=>refreshCourses(false),300000);
})();
